/**
 * Look up coordinates for an IATA airport code.
 * Returns {lat, lng} or null if not found.
 */
export function getAirportCoords(iataCode) {
  if (!iataCode) return null;
  return airportCoordinates[iataCode.toUpperCase()] || null;
}
